    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long x, y;
    cin >> x >> y;

    long long a, b;
    if ((x >= 0) == (y >= 0)) {
        a = b = x + y;
    } else {
        a = x - y;
        b = y - x;
    }

    if (a < 0)
        cout << a << " 0 0 " << b << '\n';
    else
        cout << "0 " << b << ' ' << a << " 0\n";

    return 0;
